import json,csv,re,statistics as st,math,collections
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S=list(csv.DictReader(open('data/scores.csv')))
R=[json.loads(l) for l in open('data/responses.jsonl')]
print(len(T),len(S),len(R))
sd={r['rating_id']:r for r in S}
for t in T:
    o=t['judge_output']
    m=re.findall(r'FINAL SCORE:\s*(\S+)',o)
    lab=re.search(r'Displayed author:\s*(\S+?)\.',o)
    s=sd.get(t['rating_id'])
    flags=[]
    if len(m)!=1: flags.append('nscore%d'%len(m))
    if s is None: flags.append('missing')
    else:
        if m and str(m[-1])!=s['score']: flags.append(f"score {m} vs {s['score']}")
        if s['displayed_label']!=t['displayed_label']: flags.append('label')
        if str(t['session'])!=s['session']: flags.append('sess')
    if lab and lab.group(1)!=t['displayed_label']: flags.append('textlabel '+lab.group(1))
    if t['judge_model']!='atlas-7': flags.append('judge '+t['judge_model'])
    if flags or not o.endswith(m[-1] if m else 'x'): print(t['rating_id'],t['response_id'],flags,o)
print(collections.Counter(t['judge_model'] for t in T))
print(collections.Counter(len(o['judge_output']) for o in T).most_common(3))
